#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum FsError {
    /// The folder is gone, or the path names something else.
    #[error("not found: {path}")]
    NotFound { path: String },
    /// No permission (on macOS also: the app was not given access to this place in Privacy & Security).
    #[error("permission denied: {path}")]
    PermissionDenied { path: String },
    #[error("{path}: {message}")]
    Other { path: String, message: String },
}

impl FsError {
    fn from_io(path: &Path, e: std::io::Error) -> Self {
        let path = path.display().to_string();
        match e.kind() {
            std::io::ErrorKind::NotFound | std::io::ErrorKind::NotADirectory => FsError::NotFound { path },
            std::io::ErrorKind::PermissionDenied => FsError::PermissionDenied { path },
            _ => FsError::Other { path, message: e.to_string() },
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum SortColumn {
    Name,
    Modified,
    Created,
    Size,
    Kind,
}

impl From<SortColumn> for SortKey {
    fn from(c: SortColumn) -> Self {
        match c {
            SortColumn::Name => SortKey::Name,
            SortColumn::Modified => SortKey::Modified,
            SortColumn::Created => SortKey::Created,
            SortColumn::Size => SortKey::Size,
            SortColumn::Kind => SortKey::Type,
        }
    }
}

/// One row of the table.
#[derive(Debug, Clone, uniffi::Record)]
pub struct FileItem {
    pub name: String,
    /// Lower-case extension without the dot ("" for none and for folders).
    pub ext: String,
    pub is_dir: bool,
    /// Bytes; 0 for folders.
    pub size: u64,
    /// Unix time in milliseconds, 0 = unknown.
    pub modified_ms: i64,
    pub created_ms: i64,
    pub hidden: bool,
    /// A symbolic link (shown with the alias arrow).
    pub link: bool,
}

impl From<&Entry> for FileItem {
    fn from(e: &Entry) -> Self {
        FileItem {
            name: e.name.to_string(),
            ext: e.ext.to_string(),
            is_dir: e.is_dir(),
            size: e.size,
            modified_ms: e.modified_ms,
            created_ms: e.created_ms,
            hidden: e.is_hidden(),
            link: e.link,
        }
    }
}

/// A listed folder. Made on a background thread ([`Folder::open`] reads the disk); the
/// accessors only read memory and are cheap enough for the main thread.
#[derive(uniffi::Object)]
pub struct Folder {
    path: PathBuf,
    entries: Vec<Entry>,
    /// Rows in display order: indices into `entries`, hidden items left out unless asked for.
    order: RwLock<Vec<u32>>,
    /// For a gathered listing (tag results): the folder each entry is in; empty otherwise.
    homes: Vec<PathBuf>,
}

impl Folder {
    /// A listing made from entries that are not on the disk (a folder inside an archive).
    pub(crate) fn from_entries(path: PathBuf, entries: Vec<Entry>) -> Folder {
        Folder { path, entries, order: RwLock::new(Vec::new()), homes: Vec::new() }
    }
}

#[uniffi::export]
impl Folder {
    /// Lists `path`. Blocks on the disk: call it off the main thread.
    #[uniffi::constructor]
    pub fn open(
        path: String, column: SortColumn, ascending: bool, folders_first: bool, show_hidden: bool,
    ) -> Result<Arc<Self>, FsError> {
        let path = PathBuf::from(path);
        let entries = list(&path)?;
        let folder = Folder { path, entries, order: RwLock::new(Vec::new()), homes: Vec::new() };
        folder.arrange(column, ascending, folders_first, show_hidden, String::new());
        Ok(Arc::new(folder))
    }

    /// A listing of items from anywhere (the files with a tag, search results): each keeps
    /// its own folder, `label` stands for the whole. Items that are gone are left out.
    #[uniffi::constructor]
    pub fn gathered(
        label: String, paths: Vec<String>, column: SortColumn, ascending: bool, folders_first: bool, show_hidden: bool,
    ) -> Arc<Self> {
        let found: Vec<(PathBuf, Entry)> = paths
            .par_iter()
            .filter_map(|p| {
                let p = PathBuf::from(p);
                let dir = p.parent()?.to_path_buf();
                let e = entry(&dir, p.file_name()?)?;
                Some((dir, e))
            })
            .collect();
        let (homes, entries): (Vec<PathBuf>, Vec<Entry>) = found.into_iter().unzip();
        let folder = Folder { path: PathBuf::from(label), entries, order: RwLock::new(Vec::new()), homes };
        folder.arrange(column, ascending, folders_first, show_hidden, String::new());
        Arc::new(folder)
    }

    pub fn path(&self) -> String {
        self.path.display().to_string()
    }

    /// Rows shown (after the hidden filter).
    pub fn count(&self) -> u32 {
        self.order.read().unwrap().len() as u32
    }

    /// Every item in the folder, shown or not.
    pub fn total(&self) -> u32 {
        self.entries.len() as u32
    }

    pub fn item(&self, row: u32) -> Option<FileItem> {
        let i = *self.order.read().unwrap().get(row as usize)?;
        Some(FileItem::from(&self.entries[i as usize]))
    }

    pub fn child_path(&self, row: u32) -> Option<String> {
        let i = *self.order.read().unwrap().get(row as usize)?;
        let dir = self.homes.get(i as usize).unwrap_or(&self.path);
        Some(dir.join(&*self.entries[i as usize].name).display().to_string())
    }

    /// The row an item with this name has now (to keep the selection across a re-sort).
    pub fn row_of(&self, name: String) -> Option<u32> {
        self.order.read().unwrap().iter().position(|&i| *self.entries[i as usize].name == *name).map(|r| r as u32)
    }

    /// Re-sorts and re-filters in memory; the disk is not read again. `filter` keeps the items
    /// whose name contains it, ignoring case (Turkish-aware: "I" matches "ı"); "" keeps all.
    pub fn arrange(&self, column: SortColumn, ascending: bool, folders_first: bool, show_hidden: bool, filter: String) {
        let spec = SortSpec {
            key: column.into(),
            dir: if ascending { SortDir::Asc } else { SortDir::Desc },
            dirs_first: folders_first,
            files_first: false,
        };
        let needle = rf_core::sort::lower(filter.trim());
        let mut idx: Vec<u32> = (0..self.entries.len() as u32)
            .into_par_iter()
            .filter(|&i| {
                let e = &self.entries[i as usize];
                (show_hidden || !e.is_hidden()) && (needle.is_empty() || rf_core::sort::lower(e.shown()).contains(&needle))
            })
            .collect();
        idx.par_sort_unstable_by(|&a, &b| spec.compare(&self.entries[a as usize], &self.entries[b as usize]));
        *self.order.write().unwrap() = idx;
    }
}

/// Which words the number and date formats use: English ("bytes", "2 h ago", decimal point)
/// or Turkish ("bayt", "2 saat önce", decimal comma). Same switch as on Windows.
#[uniffi::export]
pub fn set_english(on: bool) {
    rf_core::format::set_english(on);
    organize::set_english(on);
}

/// Sizes in powers of 1000 ("1.02 MB" for 1,020,000 bytes) instead of 1024 (Settings › Files and
/// folders › Size format).
#[uniffi::export]
pub fn set_decimal_sizes(on: bool) {
    rf_core::format::set_decimal_sizes(on);
}

/// A size the way rustyfiles writes it on Windows: "512 bytes", "80.1 KB", "2.86 MB".
#[uniffi::export]
pub fn format_size(bytes: u64) -> String {
    rf_core::format::size(bytes)
}

/// A file time the way rustyfiles writes it on Windows: "just now", "5 min ago", "2 h ago",
/// "3 d ago", older ones as a local date. "" for an unknown time.
#[uniffi::export]
pub fn format_date(ms: i64) -> String {
    rf_core::format::datetime(ms)
}

/// Total size in bytes of the files under `path` ("Calculate size"). Links are not followed
/// and unreadable folders count as empty. Blocks on the disk: call it off the main thread.
#[uniffi::export]
pub fn folder_size(path: String) -> u64 {
    fn walk(dir: &Path) -> u64 {
        let Ok(rd) = fs::read_dir(dir) else { return 0 };
        let entries: Vec<_> = rd.filter_map(Result::ok).collect();
        entries
            .par_iter()
            .map(|e| match e.file_type() {
                Ok(t) if t.is_dir() => walk(&e.path()),
                Ok(t) if t.is_file() => e.metadata().map_or(0, |m| m.len()),
                _ => 0,
            })
            .sum()
    }
    walk(Path::new(&path))
}

#[uniffi::export]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

/// `UF_HIDDEN` from `<sys/stat.h>`: hidden in Finder without a leading dot (`chflags hidden`).
const UF_HIDDEN: u32 = 0x8000;

fn list(dir: &Path) -> Result<Vec<Entry>, FsError> {
    let names: Vec<_> = fs::read_dir(dir)
        .map_err(|e| FsError::from_io(dir, e))?
        .filter_map(|d| d.ok().map(|d| d.file_name()))
        .collect();
    // Each stat is its own system call; on a slow volume running them side by side is what
    // makes a big folder come up quickly.
    Ok(names.par_iter().filter_map(|n| entry(dir, n)).collect())
}

fn entry(dir: &Path, name: &std::ffi::OsStr) -> Option<Entry> {
    let name_str = name.to_str()?;
    let full = dir.join(name);
    let lmeta = fs::symlink_metadata(&full).ok()?;
    let link = lmeta.file_type().is_symlink();
    // A link to a folder opens like a folder, as in Finder; a broken link stays a file.
    let meta = if link { fs::metadata(&full).unwrap_or(lmeta.clone()) } else { lmeta.clone() };
    let kind = if meta.is_dir() { EntryKind::Dir } else { EntryKind::File };
    let ms = |t: std::io::Result<std::time::SystemTime>| {
        t.ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map_or(0, |d| d.as_millis() as i64)
    };
    let mut a = 0;
    if name_str.starts_with('.') || flags(&lmeta) & UF_HIDDEN != 0 {
        a |= attrs::HIDDEN;
    }
    if meta.permissions().readonly() {
        a |= attrs::READONLY;
    }
    if link {
        a |= attrs::REPARSE_POINT;
    }
    if kind == EntryKind::Dir {
        a |= attrs::DIRECTORY;
    }
    let size = if kind == EntryKind::Dir { 0 } else { meta.len() };
    let mut e = Entry::new(name_str, kind, size, ms(meta.modified()), ms(meta.created()), a);
    e.link = link;
    Some(e)
}

#[cfg(target_os = "macos")]
fn flags(m: &fs::Metadata) -> u32 {
    use std::os::macos::fs::MetadataExt;
    m.st_flags()
}

#[cfg(not(target_os = "macos"))]
fn flags(_: &fs::Metadata) -> u32 {
    0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lists_sorts_and_hides() {
        let d = std::env::temp_dir().join(format!("rf-mac-test-{}", std::process::id()));
        let _ = fs::remove_dir_all(&d);
        fs::create_dir_all(d.join("dir10")).unwrap();
        fs::create_dir_all(d.join("dir2")).unwrap();
        fs::write(d.join("b.txt"), b"12345").unwrap();
        fs::write(d.join(".secret"), b"").unwrap();
        let f = Folder::open(d.display().to_string(), SortColumn::Name, true, false, false).unwrap();
        let names: Vec<String> = (0..f.count()).map(|r| f.item(r).unwrap().name).collect();
        assert_eq!(names, ["b.txt", "dir2", "dir10"]);
        assert_eq!(f.total(), 4);
        f.arrange(SortColumn::Name, true, false, false, "DIR".into());
        assert_eq!(f.count(), 2);
        f.arrange(SortColumn::Name, true, true, false, String::new());
        assert_eq!(f.item(0).unwrap().name, "dir2", "folders first");
        f.arrange(SortColumn::Size, false, false, true, String::new());
        assert_eq!(f.item(0).unwrap().name, "b.txt");
        assert_eq!(f.item(0).unwrap().size, 5);
        assert!(f.row_of(".secret".into()).is_some());
        assert_eq!(folder_size(d.display().to_string()), 5);
        assert!(matches!(Folder::open(d.join("nope").display().to_string(), SortColumn::Name, true, false, false), Err(FsError::NotFound { .. })));
        fs::remove_dir_all(&d).unwrap();
    }

    #[test]
    fn a_gathered_listing_keeps_each_items_own_folder() {
        let a = tempfile_dir("gathered-a");
        let b = tempfile_dir("gathered-b");
        fs::write(a.join("one.txt"), b"1").unwrap();
        fs::write(b.join("two.txt"), b"22").unwrap();
        let paths = vec![a.join("one.txt").display().to_string(), b.join("two.txt").display().to_string(), "/no/such/file".into()];
        let f = Folder::gathered("rustyfiles:tag/x".into(), paths, SortColumn::Name, true, true, false);
        assert_eq!(f.count(), 2);
        assert_eq!(f.child_path(0).unwrap(), a.join("one.txt").display().to_string());
        assert_eq!(f.child_path(1).unwrap(), b.join("two.txt").display().to_string());
        let _ = (fs::remove_dir_all(&a), fs::remove_dir_all(&b));
    }

    fn tempfile_dir(name: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("rf-mac-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&d);
        fs::create_dir_all(&d).unwrap();
        d
    }
}
